  "Install the Azure command-line tools (`az`), then enable Azure DevOps support with `az extension add --name azure-devops`.":
    "请安装 Azure 命令行工具（`az`），再运行 `az extension add --name azure-devops` 启用 Azure DevOps 支持。",
  "Install Git from https://git-scm.com/downloads or with your package manager.":
    "请从 https://git-scm.com/downloads 或使用包管理器安装 Git。",
  "Install Jujutsu with `brew install jj` or from https://github.com/jj-vcs/jj.":
    "请运行 `brew install jj`，或从 https://github.com/jj-vcs/jj 安装 Jujutsu。",
  "Install the GitHub command-line tool (`gh`) via https://cli.github.com/ or your package manager (for example `brew install gh`).":
    "请从 https://cli.github.com/ 或使用包管理器安装 GitHub 命令行工具（`gh`），例如运行 `brew install gh`。",
  "Install the GitLab command-line tool (`glab`) from https://gitlab.com/gitlab-org/cli or your package manager (for example `brew install glab`).":
    "请从 https://gitlab.com/gitlab-org/cli 或使用包管理器安装 GitLab 命令行工具（`glab`），例如运行 `brew install glab`。",
  "Set T3CODE_BITBUCKET_EMAIL and T3CODE_BITBUCKET_API_TOKEN on the server. Use a Bitbucket API token with pull request, repository, and user read scopes.":
    "请在服务器上设置 T3CODE_BITBUCKET_EMAIL 和 T3CODE_BITBUCKET_API_TOKEN，并使用具有拉取请求、仓库及用户读取权限的 Bitbucket API Token。",
  "Fetch interval": "拉取间隔",
  "This interval is configured for Git only. The shared Background activity policy still decides whether Git refreshes may run when the timer fires. Custom intervals appear as Advanced in General settings.":
    "此间隔仅用于 Git。计时触发后，共享的“后台活动”策略仍会决定是否允许 Git 刷新。自定义间隔会在常规设置中显示为“高级”。",
  "Refresh remote branch status in the background. Set this to 0 seconds if Git credentials or security keys should only be prompted by explicit Git actions.":
    "在后台刷新远程分支状态。如果 Git 凭据或安全密钥只应由明确的 Git 操作触发，请设为 0 秒。",
  "Decrease fetch interval": "缩短拉取间隔",
